	private static void assertDescriptorRestoresOnly(BitSet columns) {
		PullRestore restore = PullRestore.of(columns, 96);
		long[] saved = IntStream.range(0, 96).mapToLong(i -> 100L + i).toArray();
		long[] row = new long[saved.length];
		Arrays.fill(row, -1L);
		restore.restore(saved, row);
		int[] restoredColumns = columns.stream().toArray();
		assertArrayEquals(restoredColumns, restore.columns());
		long[] expected = new long[saved.length];
		Arrays.fill(expected, -1L);
		for (int column : restoredColumns) {
			expected[column] = saved[column];
		}
		assertArrayEquals(expected, row);
	}

